// Before 2.16.3 (3.1.2 on 3.x), a koffi callback from a core thread can crash Node, or hang or crash it at exit.
export function koffiCallbacksAreSafe(version) {
  const [major, minor, patch] = String(version).split(".").map(Number);
  const since = (m, n, p) => major === m && (minor > n || (minor === n && patch >= p));
  return major > 3 || since(3, 1, 2) || since(2, 16, 3);
}

// The Linux core has no crypto of its own, so it checks license signatures through Node.
export function installLicenseVerifier(core, koffi, platform = process.platform) {
  if (platform !== "linux" || !koffiCallbacksAreSafe(koffi.version)) return;
  const verifier = koffi.pointer(
    koffi.proto("int", ["const uint8_t *", "int", "const uint8_t *", "int", "const uint8_t *", "int"]),
  );
  let install;
  try {
    install = core.func("dal_set_license_verifier", "int", [verifier]);
  } catch {
    return;
  }
  install(koffi.register(licenseVerifyCallback(koffi), verifier));
  // A core thread's call waits for this event loop, so the loop stays up until none is in flight.
  process.on("beforeExit", () => {
    if (install(null) > 0) setTimeout(() => {}, 10);
  });
}

/**
 * The C ABI every model-specific native library implements. Everything but the
 * constructor is generic, since options in and results out are FFI payloads
 * whose schema belongs to the model. The constructor is named per model
 * (`emo_create`) so two models can also be linked into one binary.
 */
export const dalSymbols = (modelId) => ({
  create: `void* ${modelId}_create(const char*, const char*, const char*)`,
  isDownloaded: "int dal_is_downloaded(void*)",
  download: "int dal_download(void*)",
  // One entry for every modality: the input is the model's own payload, like the
 * The native core reads its host settings from the environment
 * (DAL_APP_ID, DAL_API_KEY, DAL_DEVICE_ID, DAL_LICENSE_ENDPOINT); the browser
 * entry reads the same values from `globalThis.__dal*`. Bridging them means a
 * host sets one spelling on either runtime. Each may be a string or a zero-arg
 * function, the two forms the core's own JS host read accepts. An environment
 * variable already set wins.
 *
 * Run at each load rather than once at import, so a host that imports the package
 * before setting the global is still picked up, but only until a native model
 * first loads in this process: from then on core threads read the environment,
 * and `setenv` racing a `getenv` is a use-after-free on glibc. A device id set
 * later still reaches the core, since `run` passes it per call; a key, app id or
 * endpoint set after the first load has to be in the environment already.
 */
function bridgeHostIdentity() {
  if (globalThis[NATIVE_STARTED]) return;
  for (const [name, env] of [
    ["__dalAppId", "DAL_APP_ID"],
    ["__dalApiKey", "DAL_API_KEY"],
    ["__dalDeviceId", "DAL_DEVICE_ID"],
    ["__dalLicenseEndpoint", "DAL_LICENSE_ENDPOINT"],
  ]) {
    let value;
    try {
      const raw = globalThis[name];
      value = typeof raw === "function" ? raw() : raw;
    } catch {
      continue;
    }
    if (typeof value === "string" && value && !process.env[env]) process.env[env] = value;
  }
      if (!ptr) throw new Error(`${packageName}: the model failed to run`);
      try {
        return decodeResult(ptr);
      } finally {
        lib.bufferFree(ptr);
      }
    },
    destroy: (handle) => lib.destroy(handle),
    // The C symbol is `void`, so resolving it directly would hand a caller
    // `undefined` where the wasm entry resolves `true` and both are declared
    // `Promise<boolean>`. The flush cannot report a partial failure: it either
    // returned or it threw.
    async flushTelemetry() {
      await callAsync(lib.flushTelemetry);
      return true;
    },
    withCallGroup,
  };

  // Global hook for awaiting the license requests in flight without a model
  // reference, mirroring the wasm entry (`createWasmSdk`). Gated on
  // DAL_HTTP_DEBUG; a host holding a model calls its `flushTelemetry()` instead.
  if (process.env.DAL_HTTP_DEBUG) {
    globalThis.__dalFlushTelemetry = () => core.flushTelemetry();
  }

  return {
    core,
    async open(options = {}) {
      bridgeHostIdentity();
      const onProgress = typeof options.onProgress === "function" ? options.onProgress : undefined;
      // Only an explicit cacheRoot goes down: Apple and Linux resolve their own
      // caches directory, and the core honours what it is given, so sending a
      // default would relocate every existing cache.
      const handle = core.create(options.cacheRoot ?? null, options.directory ?? null);
      globalThis[NATIVE_STARTED] = true;
      return readyModel({ core, packageName, handle, onProgress });
    },
  };
}
